    virtual void SetupPlayerInputComponent(class UInputComponent* PlayerInputComponent) override;

    // Health system
    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Health")
    float MaxHealth = 100.0f;

    UPROPERTY(VisibleAnywhere, BlueprintReadOnly, Category = "Health")
    float CurrentHealth;

    UFUNCTION(BlueprintCallable, Category = "Health")
    void TakeDamage(float DamageAmount);

    UFUNCTION(BlueprintImplementableEvent, Category = "Health")
    void OnDeath();

    // Weapon system
    UPROPERTY(EditAnywhere, BlueprintReadOnly, Category = "Weapon")
    TSubclassOf<class AWeapon> StartingWeaponClass;

    UPROPERTY(VisibleAnywhere, BlueprintReadOnly, Category = "Weapon")
    class AWeapon* CurrentWeapon;

    UFUNCTION(BlueprintCallable, Category = "Weapon")
    void EquipWeapon(class AWeapon* Weapon);

    UFUNCTION(BlueprintCallable, Category = "Weapon")
    void Fire();

private:
    UPROPERTY()
    class USpringArmComponent* CameraBoom;

    UPROPERTY()
    class UCameraComponent* FollowCamera;
};

// In .cpp file:
#include "MyCharacter.h"
#include "GameFramework/SpringArmComponent.h"
#include "Camera/CameraComponent.h"
#include "Weapon.h"

AMyCharacter::AMyCharacter()
{
    PrimaryActorTick.bCanEverTick = true;

    // Create camera
    CameraBoom = CreateDefaultSubobject<USpringArmComponent>("CameraBoom");
    CameraBoom->SetupAttachment(RootComponent);
    CameraBoom->TargetArmLength = 300.0f;

    FollowCamera = CreateDefaultSubobject<UCameraComponent>("FollowCamera");
    FollowCamera->SetupAttachment(CameraBoom);

    CurrentHealth = MaxHealth;
}

void AMyCharacter::BeginPlay()
{
    Super::BeginPlay();

    // Spawn starting weapon
    if (StartingWeaponClass)
    {
        FActorSpawnParameters SpawnParams;
        AWeapon* Weapon = GetWorld()->SpawnActor<AWeapon>(StartingWeaponClass, SpawnParams);
        EquipWeapon(Weapon);
    }
}

void AMyCharacter::TakeDamage(float DamageAmount)
{
    CurrentHealth = FMath::Clamp(CurrentHealth - DamageAmount, 0.0f, MaxHealth);

    if (CurrentHealth <= 0.0f)
    {
        OnDeath();
    }
}

void AMyCharacter::EquipWeapon(AWeapon* Weapon)
{
    if (Weapon)
    {
        CurrentWeapon = Weapon;
        Weapon->AttachToComponent(GetMesh(), FAttachmentTransformRules::SnapToTargetIncludingScale, TEXT("WeaponSocket"));
    }
}

void AMyCharacter::Fire()
{
    if (CurrentWeapon)
    {
        CurrentWeapon->Fire();
    }
}

// In UE5, enemy AI is made with Behavior Trees, Blackboards, and AIController
// Here's the C++ code equivalent for a patrolling and chasing AI

#include "CoreMinimal.h"
#include "AIController.h"
#include "BehaviorTree/BehaviorTree.h"
#include "BehaviorTree/BlackboardComponent.h"
#include "Perception/AIPerceptionComponent.h"
#include "Perception/AISenseConfig_Sight.h"
#include "EnemyAIController.generated.h"

UCLASS()
class AEnemyAIController : public AAIController
{
    GENERATED_BODY()

public:
    AEnemyAIController()
    {
        PrimaryActorTick.bCanEverTick = true;

        // Set up AI perception (sight)
        SightConfig = CreateDefaultSubobject<UAISenseConfig_Sight>("SightConfig");
        SightConfig->SightRadius = 1500.0f;
        SightConfig->LoseSightRadius = 2000.0f;
        SightConfig->PeripheralVisionAngleDegrees = 90.0f;
        SightConfig->DetectionByAffiliation.bDetectEnemies = true;
        SightConfig->DetectionByAffiliation.bDetectFriendlies = true;
        SightConfig->DetectionByAffiliation.bDetectNeutrals = true;

        PerceptionComponent = CreateDefaultSubobject<UAIPerceptionComponent>("Perception");
        PerceptionComponent->ConfigureSense(*SightConfig);
        PerceptionComponent->SetDominantSense(SightConfig->GetSenseImplementation());
        PerceptionComponent->OnPerceptionUpdated.AddDynamic(this, &AEnemyAIController::OnPerceptionUpdated);
    }

protected:
    UPROPERTY()
    UAISenseConfig_Sight* SightConfig;

    UPROPERTY(EditDefaultsOnly, Category = "AI")
    UBehaviorTree* BehaviorTree;

    virtual void BeginPlay() override
    {
        Super::BeginPlay();

        if (BehaviorTree)
        {
            RunBehaviorTree(BehaviorTree);
        }
    }

    UFUNCTION()
    void OnPerceptionUpdated(const TArray<AActor*>& UpdatedActors)
    {
        for (AActor* Actor : UpdatedActors)
        {
            FActorPerceptionBlueprintInfo Info;
            PerceptionComponent->GetActorsPerception(Actor, Info);

            if (Actor->ActorHasTag("Player"))
            {
                GetBlackboardComponent()->SetValueAsObject("TargetActor", Actor);
                GetBlackboardComponent()->SetValueAsBool("HasSeenPlayer", true);
                return;
            }
        }

        GetBlackboardComponent()->SetValueAsBool("HasSeenPlayer", false);
    }
};

