// .cpp implementation
#include "Weapon.h"
#include "Components/SkeletalMeshComponent.h"
#include "Kismet/GameplayStatics.h"
#include "DrawDebugHelpers.h"

AWeapon::AWeapon()
{
    PrimaryActorTick.bCanEverTick = true;

    WeaponMesh = CreateDefaultSubobject<USkeletalMeshComponent>("WeaponMesh");
    RootComponent = WeaponMesh;

    CurrentAmmo = MaxAmmo;
}

void AWeapon::Fire()
{
    if (bIsReloading || CurrentAmmo <= 0) return;

    CurrentAmmo--;

    // Visual effects
    if (MuzzleFlash)
        UGameplayStatics::SpawnEmitterAtLocation(GetWorld(), MuzzleFlash, WeaponMesh->GetSocketLocation("Muzzle"));

    if (FireSound)
        UGameplayStatics::PlaySoundAtLocation(GetWorld(), FireSound, GetActorLocation());

    PerformRaycast();
}

void AWeapon::PerformRaycast()
{
    FVector StartLocation = WeaponMesh->GetSocketLocation("Muzzle");
    FVector EndLocation = StartLocation + GetActorForwardVector() * 10000.0f;

    FHitResult HitResult;
    FCollisionQueryParams Params;
    Params.AddIgnoredActor(this);
    Params.AddIgnoredActor(GetOwner());

    bool bHit = GetWorld()->LineTraceSingleByChannel(
        HitResult,
        StartLocation,
        EndLocation,
        ECC_Visibility,
        Params
    );

    if (bHit)
    {
        AActor* HitActor = HitResult.GetActor();
        if (HitActor && HitActor->CanBeDamaged())
        {
            FPointDamageEvent DamageEvent(Damage, HitResult, -GetActorForwardVector(), nullptr);
            HitActor->TakeDamage(Damage, DamageEvent, GetInstigatorController(), this);
        }

        // Spawn impact effect
        UGameplayStatics::SpawnEmitterAtLocation(GetWorld(), MuzzleFlash, HitResult.Location);
    }
}

void AWeapon::Reload()
{
    if (bIsReloading || CurrentAmmo == MaxAmmo) return;

    bIsReloading = true;
    GetWorld()->GetTimerManager().SetTimer(ReloadTimerHandle, this, &AWeapon::OnReloadComplete, ReloadTime, false);
}

void AWeapon::OnReloadComplete()
{
    CurrentAmmo = MaxAmmo;
    bIsReloading = false;
}

using UnityEngine;

public class PlatformerController : MonoBehaviour
{
    [Header("Movement")]
    public float moveSpeed = 8f;
    public float jumpForce = 12f;

    [Header("Ground Check")]
    public Transform groundCheckPoint;
    public float groundCheckRadius = 0.2f;
    public LayerMask groundLayer;

    private Rigidbody2D rb;
    private SpriteRenderer sprite;
    private Animator animator;
    private bool isGrounded;
    private float moveInput;

    void Awake()
    {
        rb = GetComponent<Rigidbody2D>();
        sprite = GetComponent<SpriteRenderer>();
        animator = GetComponent<Animator>();
    }

    void Update()
    {
        // Input
        moveInput = Input.GetAxisRaw("Horizontal");

        // Flip sprite based on direction
        if (moveInput != 0)
            sprite.flipX = moveInput < 0;

        // Jump
        if (Input.GetButtonDown("Jump") && isGrounded)
        {
            rb.velocity = new Vector2(rb.velocity.x, jumpForce);
        }

        // Animator
        animator.SetFloat("Speed", Mathf.Abs(moveInput));
        animator.SetBool("IsGrounded", isGrounded);
    }

    void FixedUpdate()
    {
        // Ground check
        isGrounded = Physics2D.OverlapCircle(groundCheckPoint.position, groundCheckRadius, groundLayer);

        // Horizontal movement
        rb.velocity = new Vector2(moveInput * moveSpeed, rb.velocity.y);
    }

    void OnDrawGizmosSelected()
    {
        if (groundCheckPoint)
        {
            Gizmos.color = Color.green;
            Gizmos.DrawWireSphere(groundCheckPoint.position, groundCheckRadius);
        }
    }
}

