using System.Collections.Generic;

// ScriptableObject for item definitions (no duplication of data!)
[CreateAssetMenu(fileName = "NewItem", menuName = "Inventory/Item")]
public class ItemData : ScriptableObject
{
    public string itemName;
    public Sprite icon;
    public GameObject worldPrefab;
    public int maxStackSize = 64;
    public bool isConsumable;
    [TextArea(3, 5)]
    public string description;
}

// Inventory slot holds an item and a count
[System.Serializable]
public class InventorySlot
{
    public ItemData item;
    public int count;

    public bool IsEmpty => item == null || count <= 0;

    public void Set(ItemData newItem, int newCount)
    {
        item = newItem;
        count = newCount;
    }

    public void Clear()
    {
        item = null;
        count = 0;
    }
}

// The inventory itself
public class Inventory : MonoBehaviour
{
    public int slotCount = 20;
    public List<InventorySlot> slots = new List<InventorySlot>();

    public static Inventory Instance { get; private set; }

    void Awake()
    {
        Instance = this;
        for (int i = 0; i < slotCount; i++)
            slots.Add(new InventorySlot());
    }

    public bool AddItem(ItemData item, int count = 1)
    {
        // Try to stack with existing
        foreach (var slot in slots)
        {
            if (!slot.IsEmpty && slot.item == item && slot.count < slot.item.maxStackSize)
            {
                int canAdd = Mathf.Min(count, slot.item.maxStackSize - slot.count);
                slot.count += canAdd;
                count -= canAdd;
                if (count <= 0) return true;
            }
        }

        // Find empty slot
        foreach (var slot in slots)
        {
            if (slot.IsEmpty)
            {
                int toAdd = Mathf.Min(count, item.maxStackSize);
                slot.Set(item, toAdd);
                count -= toAdd;
                if (count <= 0) return true;
            }
        }

        Debug.LogWarning("Inventory full!");
        return false;
    }

    public void RemoveItem(ItemData item, int count = 1)
    {
        foreach (var slot in slots)
        {
            if (slot.item == item)
            {
                int toRemove = Mathf.Min(count, slot.count);
                slot.count -= toRemove;
                count -= toRemove;
                if (slot.count <= 0) slot.Clear();
                if (count <= 0) return;
            }
        }
    }

    public int GetItemCount(ItemData item)
    {
        int total = 0;
        foreach (var slot in slots)
            if (slot.item == item) total += slot.count;
        return total;
    }
}

using UnityEngine;
using System.Collections.Generic;

// Object pool reuses bullets/particles instead of creating/destroying them
// This prevents lag from garbage collection
public class ObjectPool : MonoBehaviour
{
    public static ObjectPool Instance;

    [System.Serializable]
    public class Pool
    {
        public string tag;
        public GameObject prefab;
        public int size = 10;
    }

    public List<Pool> pools;
    public Dictionary<string, Queue<GameObject>> poolDictionary;

    void Awake()
    {
        Instance = this;
        poolDictionary = new Dictionary<string, Queue<GameObject>>();

        foreach (var pool in pools)
        {
            Queue<GameObject> objectPool = new Queue<GameObject>();

            for (int i = 0; i < pool.size; i++)
            {
                GameObject obj = Instantiate(pool.prefab);
                obj.SetActive(false);
                objectPool.Enqueue(obj);
            }

            poolDictionary.Add(pool.tag, objectPool);
        }
    }

    public GameObject Spawn(string tag, Vector3 position, Quaternion rotation)
    {
        if (!poolDictionary.ContainsKey(tag))
        {
            Debug.LogWarning($"Pool with tag {tag} doesn't exist!");
            return null;
        }

        GameObject objectToSpawn = poolDictionary[tag].Dequeue();

        objectToSpawn.SetActive(true);
        objectToSpawn.transform.position = position;
        objectToSpawn.transform.rotation = rotation;

        poolDictionary[tag].Enqueue(objectToSpawn);

        return objectToSpawn;
    }
}

// Usage in a weapon script:
// ObjectPool.Instance.Spawn("Bullet", firePoint.position, firePoint.rotation);

// Return-to-pool component (put on bullet prefab)
public class PooledObject : MonoBehaviour
{
    public float lifetime = 2f;

    void OnEnable()
    {
        Invoke(nameof(ReturnToPool), lifetime);
    }

    void ReturnToPool()
    {
        gameObject.SetActive(false);
    }

    void OnDisable()
    {
        CancelInvoke();
        // Reset position and velocity for reuse
    }
}

extends CharacterBody2D

# Export makes variables editable in the inspector
@export var speed = 300.0
@export var jump_velocity = -400.0
@export var double_jump_velocity = -350.0

# Get the gravity from project settings
var gravity = ProjectSettings.get_setting("physics/2d/default_gravity")
var can_double_jump = false
var has_double_jumped = false

func _ready():
	# Called when node enters scene tree
	add_to_group("players")

func _physics_process(delta):
	# Add gravity
	if not is_on_floor():
		velocity.y += gravity * delta
		# Allow double jump when in air
		if not has_double_jumped:
			can_double_jump = true
	else:
		can_double_jump = false
		has_double_jumped = false

	# Handle jump
	if Input.is_action_just_pressed("ui_accept"):
		if is_on_floor():
			velocity.y = jump_velocity
		elif can_double_jump:
			velocity.y = double_jump_velocity
			has_double_jumped = true
			can_double_jump = false

	# Get input direction (-1, 0, or 1)
	var direction = Input.get_axis("ui_left", "ui_right")

	if direction:
		velocity.x = direction * speed
	else:
		velocity.x = move_toward(velocity.x, 0, speed)

	move_and_slide()

