// CryEngine uses a component-based approach similar to Unity
// Here's how you'd create a player in CryEngine C++:

#include <CryEntitySystem/IEntityComponent.h>
#include <CryPhysics/physinterface.h>

class CPlayerComponent : public IEntityComponent
{
public:
    // Register component
    static void Register()
    {
        auto* factory = CScriptableBase::RegisterComponent<CPlayerComponent>();
        factory->RegisterMember("Health", &CPlayerComponent::m_health);
        factory->RegisterMember("Speed", &CPlayerComponent::m_speed);
    }

    // Called when component is initialized
    void Initialize() override
    {
        // Set up physics
        SEntityPhysicalizeParams physParams;
        physParams.type = PE_LIVING;
        physParams.mass = 80.0f;
        m_pEntity->Physicalize(physParams);

        // Set up camera
        m_pEntity->LoadGeometry(1, "Objects/Characters/Player/player.cgf");
    }

    // Called every frame
    void ProcessEvent(const SEntityEvent& event) override
    {
        if (event.event == ENTITY_EVENT_UPDATE)
        {
            float frameTime = static_cast<float>(event.fParam[0]);
            UpdateMovement(frameTime);
        }
    }

    void UpdateMovement(float deltaTime)
    {
        // Movement logic here
        pe_action_move move;
        move.dir = Vec3(1, 0, 0) * m_speed * deltaTime;
        m_pEntity->GetPhysicalEntity()->Action(&move);
    }

private:
    float m_health = 100.0f;
    float m_speed = 5.0f;
};

#include <SDL2/SDL.h>
#include <vector>
#include <memory>

class Engine {
public:
    Engine() : running(false) {}

    bool init(const char* title, int width, int height) {
        if (SDL_Init(SDL_INIT_VIDEO) < 0) return false;

        window = SDL_CreateWindow(title, SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
                                    width, height, SDL_WINDOW_SHOWN);
        if (!window) return false;

        renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
        if (!renderer) return false;

        running = true;
        previousTime = SDL_GetTicks();
        return true;
    }

    void shutdown() {
        SDL_DestroyRenderer(renderer);
        SDL_DestroyWindow(window);
        SDL_Quit();
    }

    void run() {
        while (running) {
            // Calculate delta time
            Uint32 currentTime = SDL_GetTicks();
            float deltaTime = (currentTime - previousTime) / 1000.0f;
            previousTime = currentTime;

            processInput();
            update(deltaTime);
            render();

            // Cap at 60 FPS
            Uint32 frameTime = SDL_GetTicks() - currentTime;
            if (frameTime < 16) SDL_Delay(16 - frameTime);
        }
    }

private:
    void processInput() {
        SDL_Event event;
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) running = false;
            if (event.type == SDL_KEYDOWN && event.key.keysym.sym == SDLK_ESCAPE)
                running = false;

            // Forward to input system
            for (auto& system : systems) system->handleInput(event);
        }
    }

    void update(float dt) {
        for (auto& system : systems) system->update(dt);
    }

    void render() {
        SDL_SetRenderDrawColor(renderer, 0, 0, 0, 255);
        SDL_RenderClear(renderer);

        for (auto& system : systems) system->render(renderer);

        SDL_RenderPresent(renderer);
    }

    // System interface
    struct System {
        virtual ~System() = default;
        virtual void handleInput(const SDL_Event&) {}
        virtual void update(float dt) {}
        virtual void render(SDL_Renderer*) {}
    };

    SDL_Window* window = nullptr;
    SDL_Renderer* renderer = nullptr;
    bool running;
    Uint32 previousTime;
    std::vector<std::unique_ptr<System>> systems;
};

int main() {
    Engine engine;
    if (!engine.init("My Engine", 800, 600)) return 1;
    engine.run();
    engine.shutdown();
    return 0;
}
